mapper.select:


    AND cat_id = #{catId}

    AND cat_id IN (SELECT cat_id FROM cat_profile WHERE del_flag = '0' AND base_id = #{catBaseId})
    AND cat_id IN (SELECT cat_id FROM cat_profile WHERE del_flag = '0' AND ward_id = #{catWardId})


        AND cat_id IN (
            SELECT p.cat_id FROM cat_profile p
             WHERE p.del_flag = '0'
               AND p.ward_id IN (SELECT a.ward_id FROM cat_ward_auth a WHERE a.user_id = #{assistantUserId})
        )

    AND use_date = #{useDate}
    AND date_format(use_date,'%y.%m.%d') >= date_format(#{params.beginTime},'%y.%m.%d')
    AND date_format(use_date,'%y.%m.%d') <= date_format(#{params.endTime},'%y.%m.%d')
    AND time_period = #{timePeriod}
    AND drug_name = #{drugName}
    AND dosage = #{dosage}
    AND administration = #{administration}
    AND executor = #{executor}
    AND adverse_reaction = #{adverseReaction}
    AND photos = #{photos}
    AND source_type = #{sourceType}


        AND EXISTS (
            SELECT 1 FROM cat_medication_exec e
             WHERE e.cat_id = cat_medication.cat_id
               AND e.use_date = cat_medication.use_date
               AND ifnull(e.time_period, '') = ifnull(cat_medication.time_period, '')
               AND e.status = '1'
        )


        AND NOT EXISTS (
            SELECT 1 FROM cat_medication_exec e
             WHERE e.cat_id = cat_medication.cat_id
               AND e.use_date = cat_medication.use_date
               AND ifnull(e.time_period, '') = ifnull(cat_medication.time_period, '')
               AND e.status = '1'
        )

    AND diagnosis_id = #{diagnosisId}
    AND prescription_id = #{prescriptionId}
    AND del_flag = '0'

order by medication_id desc


where del_flag = '0'
  and cat_id = #{catId}
  and use_date = #{useDate}
  and ifnull(time_period, '') = ifnull(#{timePeriod}, '')
order by medication_id asc

select count(*) from cat_medication
 where del_flag = '0'
   and cat_id = #{catId}
   and use_date = #{useDate}
   and ifnull(time_period, '') = ifnull(#{timePeriod}, '')
   and drug_name = #{drugName}

select status from cat_medication_exec
 where cat_id = #{catId}
   and use_date = #{useDate}
   and ifnull(time_period, '') = ifnull(#{timePeriod}, '')
 limit 1
